using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityEnvironmentStaticCheck{
const string R="FinalEnvironmentRoadReview/MobileOptimization/StaticCheck.txt",B="FinalEnvironmentRoadBackup/BeforeStaticCheck/";static CityEnvironmentStaticCheck(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;if(job!=null){try{if(!job.MoveNext())job=null;}catch(Exception e){job=null;File.WriteAllText(R,e.ToString());Debug.LogException(e);}return;}if(!File.Exists("CityEnvironmentStaticCheck.request"))return;string mode=File.ReadAllText("CityEnvironmentStaticCheck.request").Trim();File.Delete("CityEnvironmentStaticCheck.request");try{job=Run(mode=="apply");}catch(Exception e){File.WriteAllText(R,e.ToString());Debug.LogException(e);}}
static System.Collections.IEnumerator job;static Dictionary<GameObject,bool> dynamicRoots=new Dictionary<GameObject,bool>(); static bool Safe(Transform t){var top=t.root.gameObject;bool moving;if(!dynamicRoots.TryGetValue(top,out moving)){moving=top.name.Contains("Free Racing Car")||top.name.Contains("Prometheus")||top.GetComponentInChildren<Rigidbody>(true)||top.GetComponentInChildren<CharacterController>(true)||top.GetComponentInChildren<Camera>(true)||top.GetComponentInChildren<Canvas>(true)||top.GetComponentInChildren<Animator>(true)||top.GetComponentInChildren<Animation>(true)||top.GetComponentInChildren<SkinnedMeshRenderer>(true);dynamicRoots[top]=moving;}if(moving)return false;if(t.GetComponentInParent<Rigidbody>()||t.GetComponentInParent<Animator>()||t.GetComponentInParent<Animation>()||t.GetComponentInParent<Canvas>()||t.GetComponentInParent<Camera>())return false;if(t.GetComponent<Light>()||t.GetComponent<Camera>()||t.GetComponent<SkinnedMeshRenderer>())return false;return t.GetComponent<Renderer>()||t.GetComponent<Terrain>()||t.GetComponent<Collider>()||PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)||(t.parent==null&&t.GetComponentInChildren<Renderer>(true));}
static StaticEditorFlags Flags(GameObject go){return (GameObjectUtility.GetStaticEditorFlags(go)|StaticEditorFlags.OccludeeStatic)&~StaticEditorFlags.BatchingStatic;}
static void Backup(string path){string outp=B+path;Directory.CreateDirectory(Path.GetDirectoryName(outp));if(File.Exists(path)&&!File.Exists(outp))File.Copy(path,outp);}
static System.Collections.IEnumerator Run(bool apply){dynamicRoots.Clear();var sc=SceneManager.GetActiveScene();var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var candidates=all.Where(Safe).ToArray();var changes=candidates.Where(t=>Flags(t.gameObject)!=GameObjectUtility.GetStaticEditorFlags(t.gameObject)).ToArray();var paths=candidates.Select(t=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject)).Where(p=>!string.IsNullOrEmpty(p)&&p.StartsWith("Assets/Scenes/Oasis/")&&p.EndsWith(".prefab")).Distinct().ToArray();var log=new StringBuilder();log.AppendLine("Scene="+sc.path+" eligible objects="+candidates.Length+" scene flag corrections="+changes.Length+" source prefab candidates="+paths.Length);foreach(var t in changes.Take(25))log.AppendLine("SCENE "+AnimationUtility.CalculateTransformPath(t,null)+" flags="+GameObjectUtility.GetStaticEditorFlags(t.gameObject));if(apply){Backup(sc.path);int sourceChanges=0,sourceObjects=0,completed=0;foreach(string path in paths){var content=PrefabUtility.LoadPrefabContents(path);try{var edits=content.GetComponentsInChildren<Transform>(true).Where(Safe).Where(t=>Flags(t.gameObject)!=GameObjectUtility.GetStaticEditorFlags(t.gameObject)).ToArray();if(edits.Length>0){Backup(path);foreach(var t in edits)GameObjectUtility.SetStaticEditorFlags(t.gameObject,Flags(t.gameObject));PrefabUtility.SaveAsPrefabAsset(content,path);sourceChanges++;sourceObjects+=edits.Length;}}finally{PrefabUtility.UnloadPrefabContents(content);}dynamicRoots.Clear();completed++;if(completed%25==0)File.WriteAllText(R,log.ToString()+"Source prefab checks "+completed+"/"+paths.Length+"; corrected="+sourceChanges);yield return null;}int sceneChanges=0;foreach(var t in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(Safe)){var desired=Flags(t.gameObject);if(desired==GameObjectUtility.GetStaticEditorFlags(t.gameObject))continue;GameObjectUtility.SetStaticEditorFlags(t.gameObject,desired);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);sceneChanges++;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);int missed=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(Safe).Count(t=>(GameObjectUtility.GetStaticEditorFlags(t.gameObject)&StaticEditorFlags.OccludeeStatic)==0);log.AppendLine("SUCCESS source prefabs updated="+sourceChanges+" source objects updated="+sourceObjects+" scene overrides corrected="+sceneChanges+" eligible objects still missing Static Occludee="+missed+". Dynamic rigidbody, animated, skinned, camera, light and UI branches excluded. Static Batching disabled; original occluder and other flags preserved. No mesh/material/texture/collider changes.");}File.WriteAllText(R,log.ToString());yield break;}}
